def bubble_sort(array):
    n = len(array)
    for i in range(n):
        for j in range(0, n - i - 1):
            if array[j] > array[j + 1]:
                array[j], array[j + 1] = (array[j + 1], array[j])
    return array

def insertion_sort(lst):
    for i in range(1, len(lst)):
        while i > 0 and lst[i] < lst[i - 1]:
            lst[i], lst[i - 1] = (lst[i - 1], lst[i])
            i -= 1
    return lst

def selection_sort(arr):
    sorted_arr = []
    def find_min_index(arr):
        if not arr:
            raise ValueError('array is empty')
        min_index = 0
        for i, item in enumerate(arr):
            if item <= arr[min_index]:
                min_index = i
        return min_index
    for _ in range(len(arr)):
        index = find_min_index(arr)
        sorted_arr.append(arr.pop(index))
    return sorted_arr

def quick_sort(array):
    if len(array) < 2:
        return array
    else:
        pivot = array[0]
        less = [i for i in array[1:] if i <= pivot]
        greater = [i for i in array[1:] if i > pivot]
        return quick_sort(less) + [pivot] + quick_sort(greater)

def counting_sort(arr, max_num_in_array=None):
    if not arr:
        return arr
    if max_num_in_array is None:
        max_num_in_array = max(arr)
    counts = [0] * (max_num_in_array + 1)
    for num in arr:
        counts[num] += 1
    i = 0
    for num, count in enumerate(counts):
        for _ in range(count):
            arr[i] = num
            i += 1
    return arr

def linear_search(array, target):
    for i, item in enumerate(array):
        if item == target:
            return i
    return -1

def binary_search(sorted_array, target):
    low = 0
    high = len(sorted_array) - 1
    while low <= high:
        mid = (low + high) // 2
        if target == sorted_array[mid]:
            return mid
        elif target < sorted_array[mid]:
            high = mid - 1
        elif target > sorted_array[mid]:
            low = mid + 1
    return -1

def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)

def lcm(num1, num2):
    if num1 > num2:
        num1, num2 = (num2, num1)
    for x in range(num2, num1 * num2 + 1, num2):
        if x % num1 == 0:
            return x

def is_prime(number: int) -> bool:
    if number <= 1:
        return False
    if number <= 3:
        return True
    if number % 2 == 0 or number % 3 == 0:
        return False
    factor = 5
    while factor * factor <= number:
        if number % factor == 0 or number % (factor + 2) == 0:
            return False
        factor += 6
    return True

def sieve_of_eratosthenes(n):
    primes = [True] * (n + 1)
    p = 2
    while p * p <= n:
        if primes[p]:
            for i in range(p * 2, n + 1, p):
                primes[i] = False
        p += 1
    primes = [element for element in range(2, n + 1) if primes[element]]
    return primes

def prime_factors(n):
    factors = []
    while n % 2 == 0:
        factors.append(2)
        n //= 2
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n //= i
        i += 2
    if n > 2:
        factors.append(n)
    return factors

def factorial(number):
    if number == 0 or number == 1:
        return 1
    answer = number * factorial(number - 1)
    return answer

def fibonacci(n):
    if n == 1:
        return 1
    elif n == 0:
        return 0
    else:
        return fibonacci(n - 1) + fibonacci(n - 2)

def count_digits(n: int) -> int:
    if not isinstance(n, int):
        raise TypeError('Input must be an integer')
    digits = 0
    n = abs(n)
    while True:
        n = n // 10
        digits += 1
        if n == 0:
            break
    return digits

def decimal_binary(decimal: int) -> str:
    decimal = int(decimal)
    if decimal in (0, 1):
        return str(decimal)
    div, mod = divmod(decimal, 2)
    return decimal_binary(div) + str(mod)

def is_perfect_square(num):
    i = 0
    while i * i < num:
        i += 1
    if i * i == num:
        return True
    else:
        return False

def divisors(number):
    if not isinstance(number, int):
        raise TypeError('Incorrect number type provided. Only integers are accepted.')
    divisors = []
    for i in range(1, number + 1):
        if number % i == 0:
            divisors.append(i)
    return divisors

def roman_int(text: str) -> int:
    if not text:
        return 0
    number = 0
    roman_values = {'M': 1000, 'D': 500, 'C': 100, 'L': 50, 'X': 10, 'V': 5, 'I': 1}
    for index in range(len(text) - 1):
        if roman_values[text[index]] < roman_values[text[index + 1]]:
            number -= roman_values[text[index]]
        else:
            number += roman_values[text[index]]
    return number + roman_values[text[-1]]

def count_set_bits(number: int) -> int:
    if number < 0:
        raise ValueError('the value of input must not be negative')
    result = 0
    while number:
        if number % 2 == 1:
            result += 1
        number >>= 1
    return result

def sum_of_squares(number):
    numerator = number * (number + 1) * (2 * number + 1)
    return numerator / 6

def digital_root(number: int) -> int:
    number = abs(number)
    while number >= 10:
        number = sum((int(digit) for digit in str(number)))
    return number

def is_anagram(s: str, t: str) -> bool:
    freq_s: dict[str, int] = {}
    freq_t: dict[str, int] = {}
    for char in s:
        freq_s[char] = freq_s.get(char, 0) + 1
    for char in t:
        freq_t[char] = freq_t.get(char, 0) + 1
    return freq_s == freq_t

def count_vowels(s: str) -> int:
    if not isinstance(s, str):
        raise TypeError('Input must be a string')
    vowels = 'aeiouAEIOU'
    return sum((1 for char in s if char in vowels))

def char_frequency(string):
    freq = {}
    for char in string:
        if char not in freq:
            freq[char] = 0
        freq[char] += 1
    return freq

def capitalize(string):
    if not string:
        return string
    if len(string) == 1:
        return string.upper()
    return string[0].upper() + string[1:].lower()

def caesar_cipher(text: str, shift: int) -> str:
    result = ''
    for char in text:
        code = ord(char)
        if 64 < code < 91:
            code = (code - 65 + shift) % 26 + 65
        if 96 < code < 123:
            code = (code - 97 + shift) % 26 + 97
        result = result + chr(code)
    return result

def run_length_encoding(data: str) -> str:
    if not data:
        return ''
    encoded: str = ''
    prev_char: str = ''
    count: int = 1
    for char in data:
        if char != prev_char:
            if prev_char:
                encoded += str(count) + prev_char
            count = 1
            prev_char = char
        else:
            count += 1
    return encoded + str(count) + prev_char

def is_pangram(input_string: str) -> bool:
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    return all((char in input_string.lower() for char in alphabet))

def is_isogram(string):
    characters_lower = [char.lower() for char in string if char.isalpha()]
    return len(set(characters_lower)) == len(characters_lower)

def longest_word(sentence: str) -> str:
    words = sentence.split()
    return max(words, key=len) if words else ''

def edit_distance(x, y):
    n = len(x)
    m = len(y)
    A = [[i + j for j in range(m + 1)] for i in range(n + 1)]
    for i in range(n):
        for j in range(m):
            A[i + 1][j + 1] = min(A[i][j + 1] + 1, A[i + 1][j] + 1, A[i][j] + int(x[i] != y[j]))
    return A[n][m]

def camel_snake(camel):
    if not camel:
        return camel
    return ''.join(('_' + x if 'A' <= x <= 'Z' else x for x in camel)).lower()[camel[0].isupper():]

def longest_common_prefix(m):
    if not m:
        return ''
    s1 = min(m)
    s2 = max(m)
    for i, c in enumerate(s1):
        if c != s2[i]:
            return s1[:i]
    return s1

def balanced_parentheses(input_string):
    counterparts = {')': '(', '}': '{', ']': '['}
    stack = []
    for char in input_string:
        if char in counterparts.values():
            stack.append(char)
        elif char in counterparts:
            if not stack:
                return False
            if stack.pop() != counterparts[char]:
                return False
    return not stack

def find_max(nums: list[int | float]) -> int | float:
    if len(nums) == 0:
        raise ValueError('find_max_iterative() arg is an empty sequence')
    max_num = nums[0]
    for x in nums:
        if x > max_num:
            max_num = x
    return max_num

def find_min(nums: list[int | float]) -> int | float:
    if len(nums) == 0:
        raise ValueError('find_min_iterative() arg is an empty sequence')
    min_num = nums[0]
    for num in nums:
        min_num = min(min_num, num)
    return min_num

def median(iterable, sort=True):
    s = sorted(iterable) if sort is True else list(iterable)
    n = len(s)
    if n == 0:
        raise ValueError('median() arg is an empty sequence')
    if n % 2 == 0:
        return float(s[n // 2 - 1] + s[n // 2]) / 2
    return s[n // 2]

def rotate_list(arr, k, right=True):
    n = len(arr)
    right %= n
    if right:
        k = n - k
    return arr[k:] + arr[:k]

def chunk_list(items, size):
    size = max(1, size)
    return [items[i:i + size] for i in range(0, len(items), size)]

def merge_sorted_lists(a, b):
    c = []
    while len(a) != 0 and len(b) != 0:
        if a[0] < b[0]:
            c.append(a[0])
            a.remove(a[0])
        else:
            c.append(b[0])
            b.remove(b[0])
    if len(a) == 0:
        c += b
    else:
        c += a
    return c

def two_sum(array: list[int], target: int) -> tuple[int, int] | None:
    seen = {}
    for index, num in enumerate(array):
        if num in seen:
            return (seen[num], index)
        else:
            seen[target - num] = index
    return None

def transpose(matrix: list[list[int]]) -> list[list[int]]:
    matrix[:] = [list(x) for x in zip(*matrix)]
    return matrix

def is_sorted(a):
    n = len(a)
    for i in range(0, n - 1):
        if a[i] > a[i + 1]:
            return False
    return True

def max_subarray_sum(arr, allow_empty_subarrays=False):
    if not arr:
        return 0
    max_sum = 0 if allow_empty_subarrays else float('-inf')
    curr_sum = 0.0
    for num in arr:
        curr_sum = max(0 if allow_empty_subarrays else num, curr_sum + num)
        max_sum = max(max_sum, curr_sum)
    return max_sum

def permutations(lst):
    if len(lst) == 0:
        return []
    if len(lst) == 1:
        return [lst]
    l = []
    for i in range(len(lst)):
        m = lst[i]
        rem_lst = lst[:i] + lst[i + 1:]
        for p in permutations(rem_lst):
            l.append([m] + p)
    return l

def power_set(nums: list[int]) -> list[list[int]]:
    result: list[list[int]] = [[]]
    for number in sorted(nums):
        result += [item + [number] for item in result]
    return result

def missing_number(nums: list[int]) -> int:
    missing = 0
    for index, number in enumerate(nums):
        missing ^= number
        missing ^= index + 1
    return missing

def count_occurrences(a, b):
    count = 0
    for i in a:
        if i is b or i == b:
            count += 1
    return count

def tree_height(root):
    if root is None:
        return 0
    else:
        return 1 + max(tree_height(root.left), tree_height(root.right))

def inorder_traversal(root, res=None):
    if root is None:
        return []
    if res is None:
        res = []
    inorder_traversal(root.left, res)
    res.append(root.val)
    inorder_traversal(root.right, res)
    return res

def bst_search(root, val):
    while root:
        if val > root.val:
            root = root.right
        elif val < root.val:
            root = root.left
        else:
            return True
    return False

def is_bst(root):
    stack = []
    pre = None
    while root or stack:
        while root:
            stack.append(root)
            root = root.left
        root = stack.pop()
        if pre and root.val <= pre.val:
            return False
        pre = root
        root = root.right
    return True

def count_nodes(root):
    if root is None:
        return 0
    return count_nodes(root.left) + count_nodes(root.right) + 1

def stack_push(array, *items):
    for item in items:
        array.append(item)
    return array

def fizzbuzz(number: int) -> list[int | str]:
    if number < 1:
        raise ValueError('n cannot be less than one')
    if number is None:
        raise TypeError('n cannot be None')
    result: list[int | str] = []
    for value in range(1, number + 1):
        if value % 3 == 0 and value % 5 == 0:
            result.append('FizzBuzz')
        elif value % 3 == 0:
            result.append('Fizz')
        elif value % 5 == 0:
            result.append('Buzz')
        else:
            result.append(value)
    return result

def collatz_sequence(n: int) -> list[int]:
    sequence = [n]
    while n > 1:
        n = 3 * n + 1 if n % 2 != 0 else int(n / 2)
        sequence.append(n)
    return sequence

def pascal_triangle(row_count, previous_row=[1]):
    if row_count < 0:
        raise ValueError('number of rows is negative')
    elif row_count == 0:
        return []
    temp_row = previous_row + [0]
    new_row = list(map(sum, zip(temp_row, temp_row[::-1])))
    return [previous_row] + pascal_triangle(row_count - 1, new_row)

def climb_stairs(steps: int) -> int:
    arr = [1, 1]
    for _ in range(1, steps):
        arr.append(arr[-1] + arr[-2])
    return arr[-1]

def longest_common_subsequence(s1, s2):
    cols = len(s1) + 1
    rows = len(s2) + 1
    t = [[0 for i in range(cols)] for i in range(rows)]
    max_length = 0
    for i in range(1, rows):
        for j in range(1, cols):
            if s2[i - 1] == s1[j - 1]:
                t[i][j] = 1 + t[i - 1][j - 1]
            else:
                t[i][j] = max(t[i - 1][j], t[i][j - 1])
            max_length = max(max_length, t[i][j])
    return max_length

def sign(num: float) -> int:
    if num < 0:
        return -1
    return 1 if num else 0

def gnome_sort(array: list[int]) -> list[int]:
    n = len(array)
    index = 0
    while index < n:
        if index == 0 or array[index] >= array[index - 1]:
            index += 1
        else:
            array[index], array[index - 1] = (array[index - 1], array[index])
            index -= 1
    return array

def cocktail_sort(array: list[int]) -> list[int]:
    n = len(array)
    swapped = True
    while swapped:
        swapped = False
        for i in range(1, n):
            if array[i - 1] > array[i]:
                array[i - 1], array[i] = (array[i], array[i - 1])
                swapped = True
        if not swapped:
            return array
        swapped = False
        for i in range(n - 1, 0, -1):
            if array[i - 1] > array[i]:
                array[i - 1], array[i] = (array[i], array[i - 1])
                swapped = True
    return array

def pancake_sort(array: list[int]) -> list[int]:
    if len(array) <= 1:
        return array
    for cur in range(len(array), 1, -1):
        index_max = array.index(max(array[0:cur]))
        if index_max + 1 != cur:
            if index_max != 0:
                array[:index_max + 1] = reversed(array[:index_max + 1])
            array[:cur] = reversed(array[:cur])
    return array

def exchange_sort(array: list[int]) -> list[int]:
    n = len(array)
    for i in range(n - 1):
        for j in range(i + 1, n):
            if array[i] > array[j]:
                array[i], array[j] = (array[j], array[i])
    return array

def odd_even_sort(arr):
    is_sorted = False
    while not is_sorted:
        is_sorted = True
        for i in range(1, len(arr) - 1, 2):
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = (arr[i + 1], arr[i])
                is_sorted = False
        for i in range(0, len(arr) - 1, 2):
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = (arr[i + 1], arr[i])
                is_sorted = False
    return arr

def is_numeric(string):
    try:
        int(string)
        return True
    except ValueError:
        return False

def pig_latin(word: str) -> str:
    if not (word or '').strip():
        return ''
    word = word.lower()
    if word[0] in 'aeiou':
        return f'{word}way'
    for i, char in enumerate(word):
        if char in 'aeiou':
            break
    return f'{word[i:]}{word[:i]}ay'

def is_rotation(first: str, second: str) -> bool:
    if len(first) == len(second):
        return second in first + first
    else:
        return False

def is_subsequence(needle, haystack):
    it = iter(haystack)
    for element in needle:
        if element not in it:
            return False
    return True

def longest_palindrome(s):
    S = [[False for i in range(len(s))] for j in range(len(s))]
    max_palindrome = ''
    for i in range(len(s))[::-1]:
        for j in range(i, len(s)):
            S[i][j] = s[i] == s[j] and (j - i < 3 or S[i + 1][j - 1])
            if S[i][j] and j - i + 1 > len(max_palindrome):
                max_palindrome = s[i:j + 1]
    return max_palindrome

def find_all(lst, element):
    result = []
    offset = -1
    while True:
        try:
            offset = lst.index(element, offset + 1)
        except ValueError:
            return result
        result.append(offset)

def string_int(value):
    if callable(value):
        return string_int(value())
    else:
        return int(value)

def rot13(s: str, n: int=13) -> str:
    out = ''
    for c in s:
        if 'A' <= c <= 'Z':
            out += chr(ord('A') + (ord(c) - ord('A') + n) % 26)
        elif 'a' <= c <= 'z':
            out += chr(ord('a') + (ord(c) - ord('a') + n) % 26)
        else:
            out += c
    return out

def atbash(text: str) -> str:
    translated = ''
    for char in text:
        code = ord(char)
        if char.isalpha():
            if char.isupper():
                offset = code - ord('A')
                translated += chr(ord('Z') - offset)
            elif char.islower():
                offset = code - ord('a')
                translated += chr(ord('z') - offset)
        else:
            translated += char
    return translated

def dedupe_sorted(iterable):
    seen = set()
    return [x for x in iterable if x not in seen and (not seen.add(x))]

def interleave(*arrays, **kwargs):
    anum = arrays.__len__()
    rslt = []
    length = arrays[0].__len__()
    for j in range(0, length):
        for i in range(0, anum):
            array = arrays[i]
            rslt.append(array[j])
    return rslt

def list_difference(left, right):
    blocked = set(right)
    difference = []
    for item in left:
        if item not in blocked:
            blocked.add(item)
            difference.append(item)
    return difference

def unzip(pairs):
    lst1, lst2 = ([], [])
    for x1, x2 in pairs:
        lst1.append(x1)
        lst2.append(x2)
    return (lst1, lst2)

def argmax(l, f=None):
    if f:
        l = [f(i) for i in l]
    return max(enumerate(l), key=lambda x: x[1])[0]

def is_palindrome_list(string):
    if string == string[::-1]:
        return True
    return False

def list_product(a):
    p = 1
    for x in a:
        p *= x
    return p

def last_index(array, value, from_index=None):
    index = array_len = len(array)
    try:
        from_index = int(from_index)
    except (TypeError, ValueError):
        pass
    else:
        index = max(0, index + from_index) if from_index < 0 else min(from_index, index - 1)
    while index >= 0:
        if index < array_len and array[index] == value:
            return index
        index -= 1
    return -1

def all_equal(iterable):
    try:
        shape = iterable.shape
    except AttributeError:
        pass
    else:
        if len(shape) > 1:
            message = 'The function does not works on multidimensional arrays.'
            raise NotImplementedError(message) from None
    iterator = iter(iterable)
    first = next(iterator, None)
    return all((item == first for item in iterator))

def flatten_nested(x):
    if isinstance(x, list):
        return [k for a in x for k in flatten_nested(a)]
    return [x]

def longest_increasing_subsequence(arr):
    n = len(arr)
    if n == 0:
        return 0
    res = 1
    dp = [0] * n
    dp[0] = 1
    for i in range(1, n):
        dp[i] = 1
        for j in range(0, i):
            if arr[i] > arr[j]:
                dp[i] = max(dp[i], dp[j] + 1)
        res = max(res, dp[i])
    return res

def max_profit(prices: list[int]) -> int:
    if not prices:
        return 0
    min_price = prices[0]
    max_profit: int = 0
    for price in prices:
        min_price = min(price, min_price)
        max_profit = max(price - min_price, max_profit)
    return max_profit

def move_zeros(array):
    result = []
    zeros = 0
    for element in array:
        if element == 0 and type(element) is not bool:
            zeros += 1
        else:
            result.append(element)
    result.extend([0] * zeros)
    return result

def majority_element(arr):
    length = len(arr)
    if not length:
        return
    elif length < 3:
        return arr[0]
    frequency = {}
    for elem in arr:
        if elem not in frequency:
            frequency[elem] = 0
        frequency[elem] += 1
    for elem in frequency:
        if frequency[elem] > length // 2:
            return elem

def single_number(nums: list[int]) -> int:
    result = 0
    for number in nums:
        result ^= number
    return result

def plus_one(num_arr: list[int]) -> list[int]:
    for idx in reversed(list(enumerate(num_arr))):
        num_arr[idx[0]] = (num_arr[idx[0]] + 1) % 10
        if num_arr[idx[0]]:
            return num_arr
    return [1] + num_arr

def count_divisors(n):
    n_divisors = 1
    i = 2
    while i * i <= n:
        multiplicity = 0
        while n % i == 0:
            n //= i
            multiplicity += 1
        n_divisors *= multiplicity + 1
        i += 1
    if n > 1:
        n_divisors *= 2
    return n_divisors

def is_abundant(number: int) -> bool:
    if not isinstance(number, int):
        msg = f'Input value of [number={number}] must be an integer'
        raise TypeError(msg)
    if number < 1:
        return False
    divisor_sum = 1
    for i in range(2, int(number ** 0.5) + 1):
        if number % i == 0:
            divisor_sum += i
            if i != number // i:
                divisor_sum += number // i
    return divisor_sum > number

def triangular_number(position: int) -> int:
    if position < 0:
        raise ValueError('param `position` must be non-negative')
    return position * (position + 1) // 2

def integer_square_root(n, k=2):
    if n == 0:
        return 0
    if n < 0:
        return -integer_square_root(-n, k) if k & 1 else None
    u = 1 << -(-n.bit_length() // k)
    s = u + 1
    while u < s:
        s = u
        t = (k - 1) * s + n // s ** (k - 1)
        u = t // k
    return s

def rectangle_area(length: float, width: float) -> float:
    if length < 0 or width < 0:
        raise ValueError('area_rectangle() only accepts non-negative values')
    return length * width

def triangle_area(base: float, height: float) -> float:
    if base < 0 or height < 0:
        raise ValueError('area_triangle() only accepts non-negative values')
    return base * height / 2

def standard_deviation(numbers):
    numbers = list(numbers)
    if not numbers:
        return 0
    mean = sum(numbers) / len(numbers)
    return (sum(((n - mean) ** 2 for n in numbers)) / len(numbers)) ** 0.5

def percentage(part, whole, resolution=2):
    if whole == 0:
        raise ZeroDivisionError
    percent = 100 * float(part) / float(whole)
    return round(percent, resolution) if resolution >= 1 else int(percent)

def lerp(a, b, t):
    if t < 0.0:
        return a
    if t > 1.0:
        return b
    return a + (b - a) * t

def modular_exponentiation(x, y, p):
    res = 1
    x = x % p
    while y > 0:
        if y & 1 == 1:
            res = res * x % p
        y = y >> 1
        x = x * x % p
    return res

def totient(n: int) -> int:
    result = n
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            while n % i == 0:
                n //= i
            result -= result // i
    if n > 1:
        result -= result // n
    return result

def double_factorial(num: int) -> int:
    if not isinstance(num, int):
        raise ValueError('double_factorial_iterative() only accepts integral values')
    if num < 0:
        raise ValueError('double_factorial_iterative() not defined for negative values')
    value = 1
    for i in range(num, 0, -2):
        value *= i
    return value

def is_happy_number(number: int) -> bool:
    if not isinstance(number, int) or number <= 0:
        msg = f'number={number!r} must be a positive integer'
        raise ValueError(msg)
    seen = set()
    while number != 1 and number not in seen:
        seen.add(number)
        number = sum((int(digit) ** 2 for digit in str(number)))
    return number == 1

def lucas_number(n_th_number: int) -> int:
    if not isinstance(n_th_number, int):
        raise TypeError('dynamic_lucas_number accepts only integer arguments.')
    a, b = (2, 1)
    for _ in range(n_th_number):
        a, b = (b, a + b)
    return a

def reverse_bits(number: int) -> int:
    result = 0
    for _ in range(32):
        result = (result << 1) + (number & 1)
        number >>= 1
    return result

def merge_dicts(*ds):
    result = ds[0]
    for d in ds[1:]:
        result.update(d)
    return result

def count_elements(word_list):
    word_freqs = {}
    for w in word_list:
        if w in word_freqs:
            word_freqs[w] += 1
        else:
            word_freqs[w] = 1
    return word_freqs

def is_symmetric(adjacency_matrix):
    num_columns = len(adjacency_matrix)
    for column in adjacency_matrix:
        if len(column) != num_columns:
            return False
    max_i = 0
    for j in range(num_columns):
        for i in range(max_i):
            if i == j:
                continue
            if adjacency_matrix[j][i] != adjacency_matrix[i][j]:
                return False
        max_i += 1
    return True

def rotate_matrix(matrix: list[list[int]]) -> list[list[int]]:
    result: list[list[int]] = []
    for row in reversed(matrix):
        for i, elem in enumerate(row):
            try:
                result[i].append(elem)
            except IndexError:
                result.insert(i, [])
                result[i].append(elem)
    return result

def spiral_order(matrix: list[list]) -> list[int]:
    if matrix:
        return list(matrix.pop(0)) + spiral_order([list(row) for row in zip(*matrix)][::-1])
    else:
        return []

def time_seconds(t):
    l = list(map(int, t.split(':')))
    return sum((n * sec for n, sec in zip(l[::-1], (1, 60, 3600))))

def coin_change(coins, amount):
    if amount == 0:
        return 0
    if len(coins) == 0:
        return -1
    max_value = amount + 1
    dp = [max_value for i in range(max_value)]
    dp[0] = 0
    for i in range(1, max_value):
        for c in coins:
            if c <= i:
                dp[i] = min(dp[i], dp[i - c] + 1)
    if dp[amount] == max_value:
        return -1
    return dp[amount]

def group_anagrams(strings: list[str]) -> list[list[str]]:
    anagram_map: dict[str, int] = {}
    groups: list[list[str]] = []
    group_index = 0
    for word in strings:
        sorted_word = ''.join(sorted(word))
        if sorted_word not in anagram_map:
            anagram_map[sorted_word] = group_index
            group_index += 1
            groups.append([])
            groups[-1].append(word)
        else:
            groups[anagram_map[sorted_word]].append(word)
    return groups

def unique_paths(n, m):
    m, n = (min(m, n), max(m, n))
    lvl = m + n - 2
    pos = m - 1
    comb = 1
    for i in range(1, pos + 1):
        comb *= lvl
        comb /= i
        lvl -= 1
    return int(comb + 0.001)

def house_robber(houses: list[int]) -> int:
    last, now = (0, 0)
    for house in houses:
        last, now = (now, max(last + house, now))
    return now

def luhn(card_number):
    sum = 0
    num_digits = len(card_number)
    oddeven = num_digits & 1
    for count in range(0, num_digits):
        digit = int(card_number[count])
        if not count & 1 ^ oddeven:
            digit *= 2
        if digit > 9:
            digit -= 9
        sum += digit
    return sum % 10 == 0

def preorder_traversal(root, res=None):
    if root is None:
        return []
    if res is None:
        res = []
    res.append(root.val)
    preorder_traversal(root.left, res)
    preorder_traversal(root.right, res)
    return res

def postorder_traversal(root, res=None):
    if root is None:
        return []
    if res is None:
        res = []
    postorder_traversal(root.left, res)
    postorder_traversal(root.right, res)
    res.append(root.val)
    return res

def level_order_traversal(root):
    ans = []
    if not root:
        return ans
    level = [root]
    while level:
        current = []
        new_level = []
        for node in level:
            current.append(node.val)
            if node.left:
                new_level.append(node.left)
            if node.right:
                new_level.append(node.right)
        level = new_level
        ans.append(current)
    return ans

def is_same_tree(p, q):
    if p is None and p == q:
        return True
    if p is None or q is None:
        return False
    if p.val != q.val:
        return False
    if not is_same_tree(p.left, q.left):
        return False
    if not is_same_tree(p.right, q.right):
        return False
    return True

def has_cycle(head):
    if not head or not head.next:
        return False
    slow = head
    fast = head.next
    while slow != fast:
        if fast == None or fast.next == None:
            return False
        slow = slow.next
        fast = fast.next.next
    return True

def merge_linked_lists(l1, l2):
    if not l1 or not l2:
        return l1 or l2
    if l1.val < l2.val:
        l1.next = merge_linked_lists(l1.next, l2)
        return l1
    else:
        l2.next = merge_linked_lists(l1, l2.next)
        return l2

def delete_node(head, val):
    while head and head.val == val:
        head = head.next
    if not head:
        return None
    curr = head
    while curr.next:
        if curr.next.val == val:
            curr.next = curr.next.next
        else:
            curr = curr.next
    return head

def nth_from_end(head, k):
    if not (head or k > -1):
        return False
    ahead = head
    behind = head
    for _ in range(1, k + 1):
        if ahead is None:
            raise IndexError
        ahead = ahead.next
    while ahead:
        ahead = ahead.next
        behind = behind.next
    return behind

def topological_sort(graph):
    V = range(len(graph))
    indeg = [0 for _ in V]
    for node in V:
        for neighbor in graph[node]:
            indeg[neighbor] += 1
    Q = [node for node in V if indeg[node] == 0]
    order = []
    while Q:
        node = Q.pop()
        order.append(node)
        for neighbor in graph[node]:
            indeg[neighbor] -= 1
            if indeg[neighbor] == 0:
                Q.append(neighbor)
    return order

def is_cyclic(graph):
    path = set()
    def visit(vertex):
        path.add(vertex)
        for neighbour in graph.get(vertex, ()):
            if neighbour in path or visit(neighbour):
                return True
        path.remove(vertex)
        return False
    return any((visit(v) for v in graph))

def knapsack(p, v, cmax):
    opt = [0] * (cmax + 1)
    for pi, vi in zip(p, v):
        for c in range(cmax, pi - 1, -1):
            opt[c] = max(opt[c], opt[c - pi] + vi)
    return opt[cmax]

def subset_sum(x, R):
    b = [False] * (R + 1)
    b[0] = True
    for xi in x:
        for s in range(R, xi - 1, -1):
            b[s] |= b[s - xi]
    return b[R]

def coin_change_ways(s, n):
    if n < 0:
        return 0
    table = [0] * (n + 1)
    table[0] = 1
    for coin_val in s:
        for j in range(coin_val, n + 1):
            table[j] += table[j - coin_val]
    return table[n]

def remove_key(inventory, item):
    if item in inventory:
        inventory.pop(item)
    return inventory

def is_isomorphic(s: str, t: str) -> bool:
    if len(s) != len(t):
        return False
    mapping: dict[str, str] = {}
    mapped = set()
    for char_s, char_t in zip(s, t):
        if char_s in mapping:
            if mapping[char_s] != char_t:
                return False
        else:
            if char_t in mapped:
                return False
            mapping[char_s] = char_t
            mapped.add(char_t)
    return True

def run_length_decoding(data: str) -> str:
    decoded: str = ''
    count: str = ''
    for char in data:
        if not char.isdigit():
            decoded += char * int(count)
            count = ''
        else:
            count += char
    return decoded

def valid_palindrome(text: str) -> bool:
    left = 0
    right = len(text) - 1
    while left < right:
        while left < right and (not text[left].isalnum()):
            left += 1
        while left < right and (not text[right].isalnum()):
            right -= 1
        if text[left].lower() != text[right].lower():
            return False
        left, right = (left + 1, right - 1)
    return True

def find_substring(haystack: str, needle: str) -> int:
    if len(needle) == 0:
        return 0
    if len(needle) > len(haystack):
        return -1
    for index in range(len(haystack)):
        if len(haystack) - index < len(needle):
            return -1
        if haystack[index:index + len(needle)] == needle:
            return index
    return -1

def string_permutations(elements: list | str) -> list:
    if len(elements) <= 1:
        return [elements]
    result = []
    for perm in string_permutations(elements[1:]):
        for i in range(len(elements)):
            result.append(perm[:i] + elements[0:1] + perm[i:])
    return result

def count_vowels_consonants(text: str) -> tuple[int, int]:
    vowels = set('aeiouAEIOU')
    vowel_count = 0
    consonant_count = 0
    for char in text:
        if char.isalpha():
            if char in vowels:
                vowel_count += 1
            else:
                consonant_count += 1
    return (vowel_count, consonant_count)

def longest_common_substring(s1, s2):
    m = [[0] * (1 + len(s2)) for i in range(1 + len(s1))]
    longest, x_longest = (0, 0)
    for x in range(1, 1 + len(s1)):
        for y in range(1, 1 + len(s2)):
            if s1[x - 1] == s2[y - 1]:
                m[x][y] = m[x - 1][y - 1] + 1
                if m[x][y] > longest:
                    longest = m[x][y]
                    x_longest = x
            else:
                m[x][y] = 0
    return s1[x_longest - longest:x_longest]

def first_duplicate(arr):
    seen_numbers = set()
    for num in arr:
        if num in seen_numbers:
            return num
        seen_numbers.add(num)

def next_greater_element(arr: list[float]) -> list[float]:
    result = []
    for i, outer in enumerate(arr):
        next_item: float = -1
        for inner in arr[i + 1:]:
            if outer < inner:
                next_item = inner
                break
        result.append(next_item)
    return result

def rotate_left(x, y):
    if len(x) == 0:
        return []
    y = y % len(x)
    return x[y:] + x[:y]

def equilibrium_index(arr: list[int]) -> int:
    total_sum = sum(arr)
    left_sum = 0
    for i, value in enumerate(arr):
        total_sum -= value
        if left_sum == total_sum:
            return i
        left_sum += value
    return -1

def max_of_two(a: int, b: int) -> int:
    if a > b:
        return a
    return b

def npr(n, r=None):
    if r is None:
        r = n
    if r > n or r < 0:
        return 0
    if r == 0:
        return 1
    result = 1
    for i in range(n, n - r, -1):
        result *= i
    return result

def square_area(side_length: float) -> float:
    if side_length < 0:
        raise ValueError('area_square() only accepts non-negative values')
    return side_length ** 2

def cube_volume(side_length: float) -> float:
    if side_length < 0:
        raise ValueError('vol_cube() only accepts non-negative values')
    return pow(side_length, 3)

def first_occurrence(array: list[int], query: int) -> int:
    low, high = (0, len(array) - 1)
    while low <= high:
        mid = low + (high - low) // 2
        if low == high:
            break
        if array[mid] < query:
            low = mid + 1
        else:
            high = mid
    if array[low] == query:
        return low
    return -1

def search_insert(array: list[int], val: int) -> int:
    low = 0
    high = len(array) - 1
    while low <= high:
        mid = low + (high - low) // 2
        if val > array[mid]:
            low = mid + 1
        else:
            high = mid - 1
    return low

def sort_colors(array: list[int]) -> list[int]:
    red = white = 0
    for k in range(len(array)):
        value = array[k]
        array[k] = 2
        if value < 2:
            array[white] = 1
            white += 1
        if value == 0:
            array[red] = 0
            red += 1
    return array

def min_path_sum(matrix: list[list[int]]) -> int:
    for i in range(1, len(matrix[0])):
        matrix[0][i] += matrix[0][i - 1]
    for i in range(1, len(matrix)):
        matrix[i][0] += matrix[i - 1][0]
    for i in range(1, len(matrix)):
        for j in range(1, len(matrix[0])):
            matrix[i][j] += min(matrix[i - 1][j], matrix[i][j - 1])
    return matrix[-1][-1]

def binary_gap(number: int) -> int:
    last_one_position = None
    longest_gap = 0
    index = 0
    while number != 0:
        if number & 1:
            if last_one_position is not None:
                longest_gap = max(longest_gap, index - last_one_position)
            last_one_position = index
        index += 1
        number >>= 1
    return longest_gap

def binary_gray(bin_list: str) -> str:
    b = [bin_list[0]]
    for i in range(1, len(bin_list)):
        b += str(int(bin_list[i]) ^ int(bin_list[i - 1]))
    return ''.join(b)

def cube(num):
    num_cubed = num * num * num
    return num_cubed
